#include "hip_api.h"
using namespace hip_probe;
int main(int argc,char**argv){try{if(argc!=3)throw std::runtime_error("occupancy_probe A_MODULE T_MODULE");Api a(7);a.Check(a.hipInit(0),"init");a.Check(a.hipSetDevice(0),"device");using Fn=int(*)(int*,Handle,int,size_t);auto f=reinterpret_cast<Fn>(GetProcAddress(a.dll,"hipModuleOccupancyMaxActiveBlocksPerMultiprocessor"));if(!f)throw std::runtime_error("occupancy export absent");for(int side=0;side<2;side++){Handle m;a.Check(a.LoadModule(&m,argv[side+1]),"module");for(const char*k:{"c32_wave1_mapped_b8","c32_wave1_prefix_b8d","c32_wave1_post_b8"}){Handle fn;a.Check(a.hipModuleGetFunction(&fn,m,k),"fn");int blocks=0;a.Check(f(&blocks,fn,32,0),"occupancy");printf("ACTUAL_OCCUPANCY side=%d kernel=%s block32_dynLDS0_blocks_per_multiprocessor=%d\n",side,k,blocks);}a.hipModuleUnload(m);}return 0;}catch(const std::exception&e){fprintf(stderr,"OCCUPANCY_FAIL %s\n",e.what());return 1;}}
